string prevLog = "";
string prevTarget = "";
private void Log(string argument)
{
	if (argument != prevLog)
	{
		Logging.Write(Colors.Lime, "[{0}] {1}", Name, argument);
		prevLog = argument;
	}
}
private void Log(string argument, string target)
{
	if (target != null)
	{
		if (prevLog != argument && prevTarget != target)
		{
			Logging.Write(Colors.Lime, "[{0}] {1} {2}", Name, argument, target);
			prevLog = argument; prevTarget = target;
		}
	}
	else
		if (argument != prevLog)
		{
			Logging.Write(Colors.Lime, "[{0}] {1}", Name, argument);
			prevLog = argument;
		}
}

